            identifier = sql[start:position]
            if identifier.upper() in KEYWORDS:
                tokens.append(Token(TokenType.KEYWORD, identifier.upper(), start))
            else:
                tokens.append(Token(TokenType.IDENTIFIER, identifier.lower(), start))
        elif sql[position].isdigit():
            start = position
            while position < len(sql) and sql[position].isdigit():
                position += 1
            tokens.append(Token(TokenType.INTEGER, sql[start:position], start))
        elif sql[position] == "'":
            start = position
            string_value, position = read_string_literal(sql, position)
            tokens.append(Token(TokenType.STRING, string_value, start))
        else:
            found_operator = False
            for operator in OPERATORS:
                if sql.startswith(operator, position):
                    tokens.append(Token(TokenType.OPERATOR, operator, position))
                    position += len(operator)
                    found_operator = True
                    break
            if not found_operator:
                raise SQLSyntaxError(f"unknown character: {sql[position]}")

    tokens.append(Token(TokenType.EOF, "", position))
    return tokens
